/**
 * Request Deduplication Utility
 *
 * Prevents duplicate concurrent API requests by caching in-flight requests
 * and returning shared promises for identical requests.
 *
 * Use case: When users rapidly click "Generate" or voice commands fire multiple
 * similar requests, this utility ensures only one API call is made and all
 * concurrent callers receive the same response.
 */

/**
 * Configuration options for request deduplication
 */
export interface DeduplicationOptions {
  /** Timeout in milliseconds before cache entry is automatically cleared (default: 30000) */
  timeout?: number;
  /** Whether to enable debug logging (default: false) */
  debug?: boolean;
  /** Custom key generator function for advanced use cases */
  keyGenerator?: (endpoint: string, method: string, body?: unknown) => string;
}

/**
 * Statistics tracking for deduplication behavior
 */
export interface DeduplicationStats {
  /** Number of cache hits (requests that were deduplicated) */
  hits: number;
  /** Number of cache misses (new requests that were executed) */
  misses: number;
  /** Number of requests currently in flight */
  inFlight: number;
  /** Estimated API calls saved by deduplication */
  saved: number;
}

/**
 * Unique identifier for a request, used as cache key
 * Generated from endpoint, method, and body content
 */
export type RequestKey = string;

/**
 * Internal cache entry structure
 */
export interface CacheEntry<T> {
  /** The promise representing the in-flight request */
  promise: Promise<T>;
  /** Timestamp when this entry was created */
  timestamp: number;
  /** Timeout ID for automatic cleanup */
  timeoutId?: NodeJS.Timeout;
}

/**
 * Recursively sorts object keys to ensure deterministic JSON serialization
 * This ensures identical objects produce identical keys regardless of property order
 *
 * @param obj - Any value to sort (objects, arrays, primitives)
 * @returns Sorted version of the input
 */
const sortObjectKeys = (obj: unknown): unknown => {
  if (obj === null || obj === undefined) {
    return obj;
  }

  if (Array.isArray(obj)) {
    return obj.map(sortObjectKeys);
  }

  if (typeof obj === 'object') {
    const sorted: Record<string, unknown> = {};
    const keys = Object.keys(obj).sort();

    for (const key of keys) {
      sorted[key] = sortObjectKeys((obj as Record<string, unknown>)[key]);
    }

    return sorted;
  }

  return obj;
};

/**
 * Generates a unique, deterministic key from request parameters
 * Used to identify identical concurrent requests for deduplication
 *
 * The key is generated by combining endpoint, method, and body into a
 * stable string representation. Objects are sorted by key to ensure
 * identical requests produce identical keys regardless of property order.
 *
 * @param endpoint - API endpoint (e.g., '/api/generate')
 * @param method - HTTP method (e.g., 'POST', 'GET')
 * @param body - Optional request body (will be serialized deterministically)
 * @returns Unique string key representing this request
 *
 * @example
 * ```ts
 * const key1 = generateRequestKey('/api/generate', 'POST', { prompt: 'hello', model: 'gpt-4' });
 * const key2 = generateRequestKey('/api/generate', 'POST', { model: 'gpt-4', prompt: 'hello' });
 * // key1 === key2 (true - properties are sorted internally)
 * ```
 */
export const generateRequestKey = (
  endpoint: string,
  method: string,
  body?: unknown
): RequestKey => {
  // Normalize method to uppercase for consistency
  const normalizedMethod = method.toUpperCase();

  // Build key components
  const keyParts: string[] = [normalizedMethod, endpoint];

  // Add body to key if present
  if (body !== undefined && body !== null) {
    try {
      // Sort object keys recursively for deterministic output
      const sortedBody = sortObjectKeys(body);
      const bodyString = JSON.stringify(sortedBody);
      keyParts.push(bodyString);
    } catch (error) {
      // If JSON.stringify fails (circular refs, etc.), use toString as fallback
      console.warn('[Dedup] Failed to stringify request body, using toString fallback:', error);
      keyParts.push(String(body));
    }
  }

  // Join all parts with a delimiter
  return keyParts.join('::');
};

/**
 * Cache manager for in-flight requests
 *
 * Manages a Map of currently executing requests, preventing duplicate
 * concurrent API calls by returning shared promises for identical requests.
 *
 * Generic type T represents the response type for cached requests.
 *
 * @example
 * ```ts
 * const cache = new RequestCache<ApiResponse>();
 *
 * // Store a request
 * const promise = fetch('/api/data').then(r => r.json());
 * cache.set('GET::/api/data', promise);
 *
 * // Check if request is in-flight
 * if (cache.has('GET::/api/data')) {
 *   const existingPromise = cache.get('GET::/api/data');
 *   // Use existingPromise instead of making new request
 * }
 *
 * // Clean up after completion
 * promise.finally(() => cache.delete('GET::/api/data'));
 * ```
 */
export class RequestCache<T = unknown> {
  private cache: Map<RequestKey, CacheEntry<T>>;

  constructor() {
    this.cache = new Map();
  }

  /**
   * Stores a request promise in the cache with its metadata
   *
   * @param key - Unique request identifier
   * @param promise - The in-flight request promise
   * @param timeoutId - Optional timeout for automatic cleanup
   */
  set(key: RequestKey, promise: Promise<T>, timeoutId?: NodeJS.Timeout): void {
    const entry: CacheEntry<T> = {
      promise,
      timestamp: Date.now(),
      timeoutId,
    };

    this.cache.set(key, entry);
  }

  /**
   * Retrieves an existing in-flight request promise if available
   *
   * @param key - Unique request identifier
   * @returns The cached promise, or undefined if not found
   */
  get(key: RequestKey): Promise<T> | undefined {
    const entry = this.cache.get(key);
    return entry?.promise;
  }

  /**
   * Checks if a request is currently in-flight
   *
   * @param key - Unique request identifier
   * @returns true if the request exists in cache, false otherwise
   */
  has(key: RequestKey): boolean {
    return this.cache.has(key);
  }

  /**
   * Removes a request from the cache and cleans up its timeout
   *
   * Called after a request completes (success or failure) to prevent
   * memory leaks and allow future requests to execute.
   *
   * @param key - Unique request identifier
   * @returns true if the entry was deleted, false if it didn't exist
   */
  delete(key: RequestKey): boolean {
    const entry = this.cache.get(key);

    // Clear timeout if one was set
    if (entry?.timeoutId) {
      clearTimeout(entry.timeoutId);
    }

    return this.cache.delete(key);
  }

  /**
   * Returns the number of currently in-flight requests
   *
   * @returns Count of cached requests
   */
  size(): number {
    return this.cache.size;
  }

  /**
   * Clears all cached requests and their timeouts
   *
   * Use with caution - this will affect all in-flight requests.
   * Primarily used for testing or manual cache reset.
   */
  clear(): void {
    // Clear all timeouts before clearing cache
    for (const entry of this.cache.values()) {
      if (entry.timeoutId) {
        clearTimeout(entry.timeoutId);
      }
    }

    this.cache.clear();
  }

  /**
   * Gets all cache entry keys (for debugging)
   *
   * @returns Array of all request keys currently in cache
   */
  keys(): RequestKey[] {
    return Array.from(this.cache.keys());
  }
}

/**
 * Global request cache instance shared across all deduplication calls
 * Uses unknown type to support any response type
 */
const globalCache = new RequestCache<unknown>();

/**
 * Global statistics tracking for deduplication behavior
 * Tracks cache hits, misses, in-flight requests, and estimated savings
 */
const globalStats: DeduplicationStats = {
  hits: 0,
  misses: 0,
  inFlight: 0,
  saved: 0,
};

/**
 * Gets the current deduplication statistics
 *
 * Returns metrics about cache performance including:
 * - hits: Number of requests that were deduplicated (reused existing promise)
 * - misses: Number of new requests that were executed
 * - inFlight: Number of requests currently executing
 * - saved: Estimated API calls saved by deduplication (hits count)
 *
 * @returns Current deduplication statistics
 *
 * @example
 * ```ts
 * const stats = getStats();
 * console.log(`Cache hit rate: ${stats.hits / (stats.hits + stats.misses) * 100}%`);
 * console.log(`API calls saved: ${stats.saved}`);
 * console.log(`Currently executing: ${stats.inFlight}`);
 * ```
 */
export const getStats = (): DeduplicationStats => {
  // Update inFlight count from current cache size
  globalStats.inFlight = globalCache.size();

  // Return a copy to prevent external modification
  return { ...globalStats };
};

/**
 * Resets all deduplication statistics to zero
 *
 * Use this to clear metrics, typically for testing or when starting
 * a new measurement period. Does NOT clear the cache itself.
 *
 * @example
 * ```ts
 * resetStats();
 * // Perform some operations...
 * const stats = getStats();
 * console.log(`Operations since reset: ${stats.hits + stats.misses}`);
 * ```
 */
export const resetStats = (): void => {
  globalStats.hits = 0;
  globalStats.misses = 0;
  globalStats.inFlight = 0;
  globalStats.saved = 0;
};

/**
 * Determines if deduplication logging should be enabled
 * Logs are shown in development mode OR when debug flag is explicitly set
 *
 * @param debug - Debug flag from options
 * @returns true if logging should be enabled
 */
const shouldLog = (debug: boolean): boolean => {
  return import.meta.env.DEV || debug;
};

/**
 * Wraps a request executor with deduplication logic
 *
 * This is the main deduplication function that prevents duplicate concurrent
 * API requests. When multiple identical requests are made concurrently, only
 * the first one is executed and all callers receive the same promise.
 *
 * The function generates a unique key from the request parameters, checks if
 * a request with that key is already in-flight, and either returns the existing
 * promise or executes a new request.
 *
 * Automatic cleanup ensures cache entries are removed after completion (success
 * or failure) to prevent memory leaks and allow future requests to execute.
 *
 * @typeParam T - The expected response type of the request
 * @param executor - Function that executes the actual request
 * @param endpoint - API endpoint (e.g., '/api/generate')
 * @param method - HTTP method (e.g., 'POST', 'GET')
 * @param body - Optional request body
 * @param options - Optional deduplication configuration
 * @returns Promise that resolves with the request response
 *
 * @example
 * ```ts
 * // Without deduplication, this makes 3 API calls:
 * Promise.all([
 *   fetch('/api/generate', { method: 'POST', body: JSON.stringify({ prompt: 'hello' }) }),
 *   fetch('/api/generate', { method: 'POST', body: JSON.stringify({ prompt: 'hello' }) }),
 *   fetch('/api/generate', { method: 'POST', body: JSON.stringify({ prompt: 'hello' }) })
 * ]);
 *
 * // With deduplication, this makes only 1 API call:
 * const makeRequest = () => fetch('/api/generate', {
 *   method: 'POST',
 *   body: JSON.stringify({ prompt: 'hello' })
 * }).then(r => r.json());
 *
 * Promise.all([
 *   deduplicate(makeRequest, '/api/generate', 'POST', { prompt: 'hello' }),
 *   deduplicate(makeRequest, '/api/generate', 'POST', { prompt: 'hello' }),
 *   deduplicate(makeRequest, '/api/generate', 'POST', { prompt: 'hello' })
 * ]);
 * // All three callers receive the same result from one API call
 * ```
 */
export const deduplicate = <T>(
  executor: () => Promise<T>,
  endpoint: string,
  method: string,
  body?: unknown,
  options?: DeduplicationOptions
): Promise<T> => {
  // Use custom key generator if provided, otherwise use default
  const keyGenerator = options?.keyGenerator || generateRequestKey;
  const timeout = options?.timeout ?? 30000; // Default 30 seconds
  const debug = options?.debug ?? false;
  const enableLogging = shouldLog(debug);

  // Generate unique key for this request
  const key = keyGenerator(endpoint, method, body);

  // Check if identical request is already in-flight
  // RACE CONDITION SAFETY: This check and the subsequent set() operation are
  // both synchronous and run in the same event loop tick, preventing race
  // conditions in JavaScript's single-threaded environment. Even with concurrent
  // calls, each deduplicate() invocation completes its has() check and set()
  // operation atomically before the next call's has() check executes.
  if (globalCache.has(key)) {
    // Track cache hit metrics
    globalStats.hits++;
    globalStats.saved++;

    if (enableLogging) {
      console.log(`[Dedup] Cache HIT - ${method} ${endpoint} (reusing in-flight request)`);
      console.log(`[Dedup] Stats: hits=${globalStats.hits}, misses=${globalStats.misses}, saved=${globalStats.saved}, inFlight=${globalCache.size()}`);
    }

    // Return existing promise (type assertion safe because we control cache access)
    // All concurrent callers receive the exact same promise instance, ensuring
    // they all get the same result or error
    return globalCache.get(key) as Promise<T>;
  }

  // Track cache miss metrics
  globalStats.misses++;

  if (enableLogging) {
    console.log(`[Dedup] Cache MISS - ${method} ${endpoint} (executing new request)`);
    console.log(`[Dedup] Stats: hits=${globalStats.hits}, misses=${globalStats.misses}, saved=${globalStats.saved}, inFlight=${globalCache.size()}`);
  }

  // Set up automatic timeout cleanup to prevent memory leaks
  let timeoutId: NodeJS.Timeout | undefined;

  if (timeout > 0) {
    timeoutId = setTimeout(() => {
      if (enableLogging) {
        console.warn(`[Dedup] Timeout cleanup - ${method} ${endpoint} (removing stale cache entry after ${timeout}ms)`);
      }
      globalCache.delete(key);
    }, timeout);
  }

  // Execute the request with error handling for both sync and async errors
  let promise: Promise<T>;

  try {
    // Call executor - this might throw synchronously or return a promise
    promise = executor()
      .then((result) => {
        // Clean up cache on success
        if (enableLogging) {
          console.log(`[Dedup] Request completed - ${method} ${endpoint} (cache cleanup)`);
        }
        globalCache.delete(key);
        return result;
      })
      .catch((error) => {
        // Clean up cache on failure (network errors, API errors, timeouts, etc.)
        if (enableLogging) {
          console.error(`[Dedup] Request failed - ${method} ${endpoint} (cache cleanup)`, error);
        }
        globalCache.delete(key);
        // Re-throw error so all concurrent callers receive the same rejection
        throw error;
      });
  } catch (error) {
    // Handle synchronous errors from executor (e.g., invalid parameters)
    // Clean up timeout if one was created
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
    if (enableLogging) {
      console.error(`[Dedup] Executor error - ${method} ${endpoint} (synchronous error)`, error);
    }
    // Re-throw immediately - don't cache failed requests
    throw error;
  }

  // Store promise in cache before returning
  // This ensures all subsequent identical requests will get this promise
  globalCache.set(key, promise as Promise<unknown>, timeoutId);

  return promise;
};

/**
 * Developer Tools Integration
 *
 * Exposes deduplication stats and controls in browser console for debugging.
 * Only available in development mode to prevent production exposure.
 *
 * Available console commands:
 * - window.__DEDUP_STATS__ - Get current deduplication statistics
 * - window.__DEDUP_CLEAR_CACHE__() - Clear all in-flight request cache
 * - window.__DEDUP_RESET_STATS__() - Reset all statistics to zero
 *
 * @example
 * ```js
 * // In browser console (development mode only):
 * window.__DEDUP_STATS__
 * // => { hits: 5, misses: 3, inFlight: 1, saved: 5 }
 *
 * window.__DEDUP_CLEAR_CACHE__()
 * // => Cleared 2 in-flight requests from deduplication cache
 *
 * window.__DEDUP_RESET_STATS__()
 * // => Deduplication stats reset to zero
 * ```
 */
if (import.meta.env.DEV && typeof window !== 'undefined') {
  // Expose stats as a getter property that returns current stats
  Object.defineProperty(window, '__DEDUP_STATS__', {
    get: () => getStats(),
    configurable: true,
    enumerable: true,
  });

  // Expose cache clear function
  (window as Window & { __DEDUP_CLEAR_CACHE__: () => void }).__DEDUP_CLEAR_CACHE__ = () => {
    const count = globalCache.size();
    globalCache.clear();
    console.log(`[Dedup] Cleared ${count} in-flight request${count === 1 ? '' : 's'} from deduplication cache`);
  };

  // Expose stats reset function
  (window as Window & { __DEDUP_RESET_STATS__: () => void }).__DEDUP_RESET_STATS__ = () => {
    resetStats();
    console.log('[Dedup] Deduplication stats reset to zero');
  };

  // Log availability message
  console.log('[Dedup] Developer tools available:');
  console.log('  - window.__DEDUP_STATS__ (get current stats)');
  console.log('  - window.__DEDUP_CLEAR_CACHE__() (clear in-flight requests)');
  console.log('  - window.__DEDUP_RESET_STATS__() (reset statistics)');
}
